def np_matches(A, blocks, maxseed=10000, kind='rs'):
 x=A.flat
 for seed in range(maxseed):
  if kind=='rs': p=np.random.RandomState(seed).permutation(x)
  else: p=np.random.default_rng(seed).permutation(x)
  c=p.reshape(A.shape)
  if any(np.array_equal(c,z) for z in blocks): return seed,[i for i,z in enumerate(blocks) if np.array_equal(c,z)]
 return None
